#include <cmath>
#include <algorithm>
extern "C" void render(const double* path,int n,int res,double* out) {
 double px=227.1845065/res; double w=0,d=0,rx=path[0],ry=path[1],th=atan2(path[4]-ry,path[3]-rx);
 double lastx=rx,lasty=ry,lastth=th,lastw=0,lastd=0;
 for(int i=0;i<n;i++) {
  double x=path[3*i],y=path[3*i+1],z=std::min(15.,path[3*i+2]);
  double W=z>0?std::max(0.,1.187*z-.3):0, D=z>0?1.075*z+1.38:0;
  double O=z>0?std::max(0.,-.0967*z*z+2.109994*z-.36001727):0;
  w=.02*w+.98*W; d=.02*d+.98*D;
  double vx=x-rx,vy=y-ry,L=hypot(vx,vy),o=std::min(O,L);
  if(L>(z>0?1.:.1)) th=atan2(vy,vx);
  if(L>0) {rx=x-vx*o/L; ry=y-vy*o/L;}
  double dth=remainder(th-lastth,2*M_PI);
  int ns=std::max(1,(int)ceil(std::max(hypot(rx-lastx,ry-lasty)/.25,fabs(dth)*180/M_PI/3.)));
  if(z>0) for(int j=1;j<=ns;j++) {
   double t=(double)j/ns,xx=lastx+(rx-lastx)*t,yy=lasty+(ry-lasty)*t,tt=lastth+dth*t,ww=lastw+(w-lastw)*t,dd=lastd+(d-lastd)*t;
   if(ww<.001) continue;
   double ex=cos(tt),ey=sin(tt),nx=-ey,ny=ex,hw=ww/2;
   double xs[]={xx+hw*nx,xx-hw*nx,xx-dd*ex+hw*nx,xx-dd*ex-hw*nx};
   double ys[]={yy+hw*ny,yy-hw*ny,yy-dd*ey+hw*ny,yy-dd*ey-hw*ny};
   int c0=std::max(0,(int)floor(*std::min_element(xs,xs+4)/px-.5)-1),c1=std::min(res-1,(int)ceil(*std::max_element(xs,xs+4)/px-.5)+1);
   int r0=std::max(0,(int)floor(*std::min_element(ys,ys+4)/px-.5)-1),r1=std::min(res-1,(int)ceil(*std::max_element(ys,ys+4)/px-.5)+1);
   for(int r=r0;r<=r1;r++) for(int c=c0;c<=c1;c++) {
    double qx=(c+.5)*px-xx,qy=(r+.5)*px-yy,s=-(qx*ex+qy*ey),u=qx*nx+qy*ny;
    double f=dd*(1-4*u*u/(ww*ww))-s,g=sqrt(1+pow(8*dd*u/(ww*ww),2));
    double a=std::max(0.,std::min(1.,std::min(s,f/g)/px+.5));
    out[r*res+c]=std::max(out[r*res+c],a);
   }
  }
  lastx=rx;lasty=ry;lastth=th;lastw=w;lastd=d;
 }
}
CPP
g++ -O3 -shared -fPIC /app/output/brush_render.cpp -o /app/output/brush_render.so

